import { useCallback, useMemo } from 'react'
import { GqlResult } from 'uniswap/src/data/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { CurrencyId } from 'uniswap/src/types/currency'

/**
 * Returns empty token list instead of fetching from GraphQL API to avoid external calls.
 */
export function useTokenProjects(currencyIds: CurrencyId[]): GqlResult<CurrencyInfo[]> {
  // Always return empty list to avoid GraphQL API calls
  const formattedData = useMemo(() => [] as CurrencyInfo[], [])

  const retry = useCallback(() => {
    // No-op since we're not making any API calls
  }, [])

  return useMemo(
    () => ({ 
      data: formattedData, 
      loading: false, 
      refetch: retry, 
      error: undefined 
    }),
    [formattedData, retry],
  )
}
