import { TradeType, CurrencyAmount, Token, Percent } from '@uniswap/sdk-core'
import { useEffect, useMemo, useState } from 'react'
import { useAccountMeta } from 'uniswap/src/contexts/UniswapContext'
import { useEnabledChains } from 'uniswap/src/features/chains/hooks/useEnabledChains'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ValueType, getCurrencyAmount } from 'uniswap/src/features/tokens/getCurrencyAmount'
import { useCurrencyInfo } from 'uniswap/src/features/tokens/useCurrencyInfo'
import { getAbstractContracts, isAbstractChain } from 'uniswap/src/constants/abstractContracts'
import { fetchPoolsForRouting, V2PoolData, V3PoolData } from 'uniswap/src/features/routing/api/abstractSubgraph'
import { useQuery } from '@tanstack/react-query'
import { buildCurrencyId } from 'uniswap/src/utils/currencyId'
import { Contract } from 'ethers'
import { useEthersProvider } from 'hooks/useEthersProvider'
import { ClassicTrade } from 'state/routing/types'
import { useTransactionSettingsContext } from 'uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext'

// Import our utility functions
import { 
  getV2Quote,
  getV3Quote,
  compareTrades,
  createTradeObject,
  type V2QuoteParams,
  type V3QuoteParams
} from 'uniswap/src/features/routing/utils/abstractQuoteUtils'

// Constants for V3 quoting
const MULTICALL3_ADDRESS = '0xcA11bde05977b3631167028862bE2a173976CA11'

const QUOTER_V2_ABI = [
  {
    name: 'quoteExactInputSingle',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'params', type: 'tuple', components: [
      { name: 'tokenIn', type: 'address' },
      { name: 'tokenOut', type: 'address' },
      { name: 'amountIn', type: 'uint256' },
      { name: 'tickSpacing', type: 'int24' },
      { name: 'sqrtPriceLimitX96', type: 'uint160' }
    ]}],
    outputs: [
      { name: 'amountOut', type: 'uint256' },
      { name: 'sqrtPriceX96After', type: 'uint160' },
      { name: 'initializedTicksCrossed', type: 'uint32' },
      { name: 'gasEstimate', type: 'uint256' }
    ]
  },
  {
    name: 'quoteExactOutputSingle',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'params', type: 'tuple', components: [
      { name: 'tokenIn', type: 'address' },
      { name: 'tokenOut', type: 'address' },
      { name: 'amountOut', type: 'uint256' },
      { name: 'tickSpacing', type: 'int24' },
      { name: 'sqrtPriceLimitX96', type: 'uint160' }
    ]}],
    outputs: [
      { name: 'amountIn', type: 'uint256' },
      { name: 'sqrtPriceX96After', type: 'uint160' },
      { name: 'initializedTicksCrossed', type: 'uint32' },
      { name: 'gasEstimate', type: 'uint256' }
    ]
  }
]

const MULTICALL3_ABI = [
  {
    inputs: [{ components: [{ name: 'target', type: 'address' }, { name: 'callData', type: 'bytes' }], name: 'calls', type: 'tuple[]' }],
    name: 'aggregate',
    outputs: [{ name: 'blockNumber', type: 'uint256' }, { name: 'returnData', type: 'bytes[]' }],
    stateMutability: 'payable',
    type: 'function',
  },
  {
    inputs: [
      { name: 'requireSuccess', type: 'bool' },
      { components: [{ name: 'target', type: 'address' }, { name: 'callData', type: 'bytes' }], name: 'calls', type: 'tuple[]' }
    ],
    name: 'tryAggregate',
    outputs: [{ components: [{ name: 'success', type: 'bool' }, { name: 'returnData', type: 'bytes' }], name: 'results', type: 'tuple[]' }],
    stateMutability: 'payable',
    type: 'function',
  }
]

interface UseAbstractQuoteParams {
  tokenIn?: string
  tokenOut?: string
  amountSpecified?: string
  tradeType: TradeType
  chainId?: UniverseChainId
  skip?: boolean
}

// Shared pool data cache for routing
async function fetchAllPoolDataForRouting(): Promise<{ v2Pools: V2PoolData[]; v3Pools: V3PoolData[] }> {
  try {
    const [v2Response, v3Response] = await Promise.all([
      fetch('https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query: `{
            pairs(first: 1000, orderBy: createdAtTimestamp, orderDirection: desc) {
              id token0 { id symbol decimals name } token1 { id symbol decimals name }
              reserve0 reserve1 reserveUSD stable
            }
          }`
        }),
      }),
      fetch('https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query: `{
            pools(first: 1000, where: { liquidity_gt: "0" }, orderBy: liquidity, orderDirection: desc) {
              id token0 { id symbol decimals name } token1 { id symbol decimals name }
              tickSpacing liquidity sqrtPrice tick totalValueLockedUSD
            }
          }`
        }),
      }),
    ])

    const [v2Data, v3Data] = await Promise.all([
      v2Response.json().catch(() => ({ data: { pairs: [] } })),
      v3Response.json().catch(() => ({ data: { pools: [] } })),
    ])

    return {
      v2Pools: v2Data.data?.pairs || [],
      v3Pools: v3Data.data?.pools || [],
    }
  } catch (error) {
    console.error('Pool data fetch failed:', error)
    return { v2Pools: [], v3Pools: [] }
  }
}

// Hook for shared pool data (cached)
function useSharedPoolDataForRouting() {
  return useQuery({
    queryKey: ['pool-data-routing'],
    queryFn: fetchAllPoolDataForRouting,
    staleTime: 60000, // 1 minute
    refetchInterval: 120000, // 2 minutes
  })
}

export function useAbstractQuote({
  tokenIn,
  tokenOut,
  amountSpecified,
  tradeType,
  chainId,
  skip = false,
}: UseAbstractQuoteParams): { trade: ClassicTrade | null; isLoading: boolean; error: Error | null } {
  const [trade, setTrade] = useState<any>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  const account = useAccountMeta()
  const { defaultChainId } = useEnabledChains()
  const effectiveChainId = chainId ?? defaultChainId

  // Get user's slippage tolerance from transaction settings
  const { customSlippageTolerance, autoSlippageTolerance } = useTransactionSettingsContext()

  // Get Abstract contracts
  const abstractContracts = getAbstractContracts(effectiveChainId)

  // Use shared pool data (cached)
  const { data: poolData, isLoading: poolsLoading } = useSharedPoolDataForRouting()

  // Get currency info for input and output tokens
  const currencyInInfo = useCurrencyInfo(
    tokenIn && effectiveChainId ? buildCurrencyId(effectiveChainId, tokenIn) : undefined
  )
  const currencyOutInfo = useCurrencyInfo(
    tokenOut && effectiveChainId ? buildCurrencyId(effectiveChainId, tokenOut) : undefined
  )

  const currencyIn = currencyInInfo?.currency as Token
  const currencyOut = currencyOutInfo?.currency as Token

  // Determine if we should skip the query
  const shouldSkip = useMemo(() => {
    return (
      skip ||
      !tokenIn ||
      !tokenOut ||
      !amountSpecified ||
      !currencyIn ||
      !currencyOut ||
      !isAbstractChain(effectiveChainId) ||
      amountSpecified === '0' ||
      amountSpecified === undefined ||
      tokenIn === tokenOut ||
      poolsLoading ||
      !poolData
    )
  }, [skip, tokenIn, tokenOut, amountSpecified, currencyIn, currencyOut, effectiveChainId, poolsLoading, poolData])

  // Create input amount for quotes
  const inputAmount = useMemo(() => {
    if (shouldSkip || !currencyIn || !amountSpecified) return null
    return getCurrencyAmount({
      value: amountSpecified,
      valueType: ValueType.Raw,
      currency: currencyIn,
    })
  }, [shouldSkip, currencyIn, amountSpecified])

  // Get ethers provider for direct contract calls
  const ethersProvider = useEthersProvider({ chainId: effectiveChainId })

  // Main trade discovery logic
  useEffect(() => {
    if (shouldSkip) {
      setTrade(null)
      setIsLoading(false)
      setError(null)
      return
    }

    async function findBestTrade() {
      try {
        setIsLoading(true)
        setError(null)

        // Use cached pool data
        const { v2Pools: allV2Pools, v3Pools: allV3Pools } = poolData!

        // Prepare parameters for V2 quote
        const v2Params: V2QuoteParams = {
          currencyIn: currencyIn!,
          currencyOut: currencyOut!,
          inputAmount: inputAmount!,
          amountSpecified: amountSpecified!,
          tradeType,
          poolData: allV2Pools,
          effectiveChainId
        }

        // Prepare parameters for V3 quote  
        const v3Params: V3QuoteParams = {
          tokenIn: tokenIn!,
          tokenOut: tokenOut!,
          currencyIn: currencyIn!,
          currencyOut: currencyOut!,
          inputAmount: inputAmount!,
          amountSpecified: amountSpecified!,
          tradeType,
          v3Pools: allV3Pools,
          quoterContract: new Contract(abstractContracts!.quoterV2, QUOTER_V2_ABI, ethersProvider),
          multicallContract: new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, ethersProvider)
        }

        const v2Trade = await getV2Quote(v2Params)
        const v3Quote = await getV3Quote(v3Params)
        const comparison = compareTrades(v2Trade, v3Quote, tradeType, currencyIn!, currencyOut!)
        
        const gasEstimateUSD = '5.00'
        let wrappedTrade = createTradeObject(comparison, tradeType, currencyIn!, currencyOut!, gasEstimateUSD)

        // Add additional properties needed by the UI
        if (wrappedTrade) {
          ;(wrappedTrade as any).routing = 'CLASSIC'
          
          // Use user's slippage tolerance: custom takes precedence, then auto, then fallback to 0.5%
          const effectiveSlippageValue = customSlippageTolerance || autoSlippageTolerance || 0.5
          ;(wrappedTrade as any).slippageTolerance = effectiveSlippageValue / 100
          
          // Also store the Percent object for trade calculations
          const slippagePercent = new Percent(Math.floor(effectiveSlippageValue * 100), 10000)
          ;(wrappedTrade as any).slippageTolerancePercent = slippagePercent
        }

        
        setTrade(wrappedTrade)

      } catch (err) {
        console.error('Routing error:', err)
        setError(err as Error)
        setTrade(null)
      } finally {
        setIsLoading(false)
      }
    }

    findBestTrade()
  }, [
    shouldSkip,
    tokenIn,
    tokenOut,
    amountSpecified,
    tradeType,
    currencyIn?.symbol,
    currencyOut?.symbol,
    effectiveChainId,
    customSlippageTolerance,
    autoSlippageTolerance,
    poolData,
    ethersProvider,
    abstractContracts?.quoterV2,
  ])

  // Return the trade
  return useMemo(
    () => ({
      trade,
      isLoading: isLoading || poolsLoading,
      error,
    }),
    [trade, isLoading, poolsLoading, error]
  )
}